package hexadecimal

import "strings"

const maxInt64 = 9223372036854775807

// hexError is an error from ParseHex whose message contains the error case
// name ("syntax" or "range").
type hexError struct {
	caseName string
	msg      string
}

func (e *hexError) Error() string {
	return e.caseName + " error: " + e.msg
}

func syntaxError(msg string) error {
	return &hexError{caseName: "syntax", msg: msg}
}

func rangeError(msg string) error {
	return &hexError{caseName: "range", msg: msg}
}

// hexDigit converts a single hexadecimal character to its numeric value.
func hexDigit(c byte) (int64, bool) {
	switch {
	case c >= '0' && c <= '9':
		return int64(c - '0'), true
	case c >= 'a' && c <= 'f':
		return int64(c-'a') + 10, true
	case c >= 'A' && c <= 'F':
		return int64(c-'A') + 10, true
	}
	return 0, false
}

// ParseHex converts a hexadecimal string (e.g. "10af8c") to its decimal
// equivalent, using first principles. It returns an error whose message
// contains "syntax" for malformed input and "range" for values that do not
// fit in an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, syntaxError("empty input")
	}
	var val int64
	for i := 0; i < len(in); i++ {
		d, ok := hexDigit(in[i])
		if !ok {
			return 0, syntaxError("invalid character " + quote(in[i]))
		}
		if val > (maxInt64-d)/16 {
			return 0, rangeError("value out of int64 range")
		}
		val = val*16 + d
	}
	return val, nil
}

func quote(c byte) string {
	if c < 0x20 || c >= 0x7f {
		return string(rune(c))
	}
	return "'" + string(c) + "'"
}

// HandleErrors calls ParseHex on each input and returns a matching list of
// error cases: "none", "syntax", or "range".
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		results[i] = "none"
		if _, err := ParseHex(in); err != nil {
			switch e := err.(type) {
			case *hexError:
				results[i] = e.caseName
			}
		}
	}
	return results
}

var _ = strings.Contains // keep strings import if message-based checks are added later

